import{a as e}from"./chunk-UFTGNN3O.js";import{a as r}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var v=r(e,["Google Drive에서","다음 줄","이전 줄","이 사이트는 페이지 안에서 재생할 수 없어요. 이 창을 닫고 새 창에서 열기를 사용하세요.","{name} 클립 삭제",'"{name}" 클립을 삭제했어요',"편집","끝은 시작보다 뒤여야 해요","클립 끝 시간","끝","{a}부터","시작","전체 화면","여기서 동영상을 재생하면 클립이 현재 위치에서 시작해요. 시간을 입력해도 돼요. 예: 2:15.","Google Drive 플레이어는 재생 위치를 페이지에 알려 주지 않으니, 플레이어를 보고 시간을 입력하세요. 예: 2:15.","동영상의 현재 위치에서 시작해요. 끝나는 곳에서 지금을 누르거나 시간을 입력하세요.","클립 {n}","클립 내용","보여 주는 내용, 예: 강렬한 도입","클립이 시작하는 시간을 입력하세요. 예: 2:15","클립","이 동영상의 한 부분을 저장해 나중에 학급에 보여 주기","다음 클립","잘리는 것은 없어요. 클립은 두 시간과 라벨일 뿐이에요.","지금","{n} / {of}","이 부분 재생","이전 클립","클립 저장","변경 사항 저장","학급에 보여 주기","전체 화면, 라벨은 보이고 학생 이름은 숨김","{a} – {b}","학급에 보여 주는 클립","클립 시작 시간","{b}에서 멈추기","끝","Google 드라이브","이 동영상은 Drive에서 바로 재생되지 않았어요. 오프라인용으로 내려받거나 Drive 플레이어에서 보세요.","Drive에서 고르기…","폴더 바꾸기","내려받은 파일 삭제","내려받은 파일을 삭제했어요. 동영상은 Drive에 그대로 있어요.","오프라인용으로 내려받기","오프라인용으로 내려받기({size})","Drive에서 내려받는 중… {p}%","Drive에 따르면 지금은 이 동영상을 쓸 수 없어요. 휴지통으로 옮겨졌거나 다른 Google 계정으로 골랐을 수 있어요. 추가에서 동영상을 눌러 다시 고르세요.","Google Drive \xB7 내려받음","이 브라우저에 보관되어 인터넷 없이도 재생돼요. 내려받은 파일 삭제를 누르면 공간이 비워져요. Drive의 동영상은 그대로예요.","Drive가 지금 이 동영상을 넘겨주지 않아요. Drive 플레이어에서 보세요.","Drive에서 조금씩 불러와 재생하고, 대본이 함께 따라가요. 작업에는 링크만 저장돼요.","내려받으면 여기서 대본과 함께 재생할 수 있고, Drive 플레이어에서 볼 수도 있어요. 작업에는 링크만 저장되고 동영상은 Drive에 그대로 있어요.","고른 동영상만 열 수 있고, 드라이브의 다른 것은 열 수 없습니다.","Drive에서 동영상을 여는 중…","Drive에서 재생","이 컴퓨터에 이 동영상({size})을 저장할 공간이 없어요. 내려받지 않고 보세요.","Drive에서 동영상을 고르세요. Drive에서 재생하거나 오프라인용으로 내려받을 수 있어요. 작업에는 링크만 저장돼요.","이 동영상을 재생하려면 Google로 로그인한 뒤 버튼을 다시 누르세요.","Google Drive에서 재생 중","Drive에서 조금씩 불러와 재생해요. 이 브라우저에는 아무것도 복사되지 않아요.","Drive 플레이어에서 보기","이 브라우저에서는 이 동영상의 소리만 재생됩니다. iPhone 동영상은 컴퓨터에서 열어야 화면이 보일 수 있습니다. 내려받거나 학생에게 .mp4를 부탁하세요.","드라이브…","드라이브에서 고르기…",{one:"이 파일은 이름과 맞지 않았습니다: {names}. 맞는 줄에서 드라이브…를 사용하세요.",other:"이 파일들은 이름과 맞지 않았습니다: {names}. 맞는 줄에서 드라이브…를 사용하세요."},"동영상과 파트너","선택 사항이며 나중에 추가할 수도 있습니다. 동영상마다 링크를 붙여넣거나 파일을 고르세요. 동영상 파일을 여기에 놓으면 파일 이름에 있는 학생에게 각각 갑니다. 파트너는 메모 페이지 하나, 표시 한 벌, 성적 하나를 함께 씁니다.","시간은 동영상이나 현장 발표용 타이머가 알려 줍니다","다시 만들기","대본을 다시 만들까요? 지금 있는 것은 바뀝니다.",{one:"{name}님과 파트너 1명에게 추가",other:"{name}님과 파트너 {n}명에게 추가"},"파트너","동영상에 나오는 다른 사람을 모두 체크하세요. 그들도 동영상과 메모 페이지를 받고, 그룹 전체에 표시 한 벌과 성적 하나가 적용됩니다.","동영상이 돌아왔습니다"],null);export{v as default};
